use vstd::vec::Vec;
use vstd::seq::Seq;

verus! {

    /// Delete `p` characters starting at index `at` within the first `l` characters
    /// of `line`, and truncate the vector to length `l - p`.
    ///
    /// Preconditions:
    ///   0 ≤ l ≤ line.len()
    ///   0 ≤ at, 0 ≤ p, and at + p ≤ l
    ///
    /// Postconditions:
    ///   line.len() == l - p
    ///   line@ == old(line@).slice(0, at) + old(line@).slice(at + p, l)
    fn delete(line: &mut Vec<char>, l: usize, at: usize, p: usize)
        requires
            l <= line.len(),
            at + p <= l,
        ensures
            line.len() == l - p,
        ensures
            line@ ==
                old(line@).slice(0, at)
                + old(line@).slice(at + p, l)
    {
        // Take a snapshot of the original contents.
        let old_line: Seq<char> = line@;

        // We will shift elements leftward, one by one, starting from `at`
        // until we've moved all elements in the range [at+p, l).
        let mut i: usize = at;
        while i < l - p
            invariant at <= i
            invariant i <= l - p
            invariant forall |k: usize| k < i ==>
                // For each position k < i, we've already fixed
                // line[k] to match the intended post‐deletion character.
                line[k] ==
                    if k < at {
                        old_line[k]
                    } else {
                        old_line[k + p]
                    }
            decreases (l - p) - i
        {
            // Shift the element at `i + p` down to position `i`.
            line[i] = line[i + p];
            i += 1;
        }

        // Truncate off the now‐redundant tail.
        line.truncate(l - p);
    }

}